glsl3.vert:
precision mediump float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 spriteColor;
out vec2 uv;
layout(std140) uniform Vs {
  float sampleFromRt;
};
vec4 vert() {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  #if USE_PIXEL_ALIGNMENT
    pos = cc_matView * pos;
    pos.xyz = floor(pos.xyz);
    pos = cc_matProj * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  uv = a_texCoord;
  if (sampleFromRt == 1.0 && cc_cameraPos.w > 1.0) {
    uv.y = 1.0 - uv.y;
  }
  spriteColor = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision mediump float;
uniform sampler2D cc_spriteTexture;
in vec4 spriteColor;
in vec2 uv;
layout(std140) uniform Fs {
  vec4 outerColor;
  vec4 innerColor;
  vec2 texSize;
  float enable;
  float outerActive;
  float outerStyle;
  float outerWidth;
  float innerActive;
  float innerStyle;
  float innerWidth;
  float brightness;
  float centerScale;
};
vec4 getColor(sampler2D tex, vec2 uv) {
  return uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0 ? vec4(0, 0, 0, 0) : texture(tex, uv);
}
#define ALPHA_THRESHOLD 0.5
#define ANGLE_COUNT 36
#define JOINT_COUNT 20
vec4 frag() {
  vec2 scaleUv = (uv - vec2(0.5, 0.5) * (1.0 - centerScale)) / centerScale;
  vec4 o = getColor(cc_spriteTexture, scaleUv) * spriteColor;
  if (enable == 0.0) { return o; }
  float radianStep = 6.2831853 / float(ANGLE_COUNT);
  if (o.a < ALPHA_THRESHOLD) {
    if (outerActive == 1.0) {
      float jointStep = outerWidth / float(JOINT_COUNT);
      float width = (outerWidth + jointStep) * min(brightness, 1.0);
      float minDis = width;
      for(int i = 0; i < ANGLE_COUNT; i ++ ) {
        float radian = float(i) * radianStep;
        vec2 dirVec = vec2(cos(radian), sin(radian));
        for(int j = 0; j <= JOINT_COUNT; j ++ ) {
          float dist = float(j) * jointStep;
          if (getColor(cc_spriteTexture, scaleUv + (dist / texSize) * dirVec).a > ALPHA_THRESHOLD) {
            minDis = min(minDis, dist);
            break;
          }
        }
      }
      if (minDis < width) {
        if (outerStyle == 0.0)o = outerColor;
        else if (outerStyle == 1.0)o = vec4(outerColor.rgb, outerColor.a * smoothstep(width, 0.0, minDis));
        else if (outerStyle == 2.0)o = outerColor * smoothstep(width, 0.0, minDis);
      }
    }
  }else {
    if (innerActive == 1.0) {
      float jointStep = innerWidth / float(JOINT_COUNT);
      float width = (innerWidth + jointStep) * min(brightness, 1.0);
      float minDis = width;
      for(int i = 0; i < ANGLE_COUNT; i ++ ) {
        float radian = float(i) * radianStep;
        vec2 dirVec = vec2(cos(radian), sin(radian));
        for(int j = 0; j <= JOINT_COUNT; j ++ ) {
          float dist = float(j) * jointStep;
          if (getColor(cc_spriteTexture, scaleUv + (dist / texSize) * dirVec).a < ALPHA_THRESHOLD) {
            minDis = min(minDis, dist);
            break;
          }
        }
      }
      if (minDis < width) {
        if (innerStyle == 0.0)o = innerColor;
        else if (innerStyle == 1.0)o.rgb = mix(o.rgb, innerColor.rgb, innerColor.a * smoothstep(innerWidth, 0.0, minDis));
        else if (innerStyle == 2.0) {
          vec4 c = innerColor * smoothstep(width, 0.0, minDis);
          o.rgb = mix(o.rgb, c.rgb, c.a);
        };
      }
    }
  }
  if (outerActive == 1.0) {
    o.rgb = mix(o.rgb, outerColor.rgb, brightness * 0.1);
  }
  o.rgb *= brightness;
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

